import subprocess, re, collections, os
branches=['rachel','monica','phoebe','joey','chandler','ross']
msgs=[]
for b in branches:
    out=subprocess.check_output(['git','log',f'origin/friend/{b}','--format=%H%x1f%ci'], text=True)
    for line in out.splitlines():
        sha,dt=line.split('\x1f',1)
        full=subprocess.check_output(['git','show','-s','--format=%B',sha], text=True)
        if not re.search(r'^Friend-Message:\s*1\s*$', full, re.M):
            continue
        m_ep=re.search(r'^Episode:\s*(.+)$',full,re.M)
        m_speaker=re.search(r'^Speaker:\s*(.+)$',full,re.M)
        if m_ep and m_ep.group(1).strip()=='S07/E01':
            msgs.append((sha,dt,b,m_speaker.group(1).strip(),full))
recorded=set()
for root,_,files in os.walk('.'):
    for f in files:
        if re.match(r'S\d+/E\d+\.md', os.path.join(root,f).lstrip('./')):
            txt=open(os.path.join(root,f)).read()
            for m in re.finditer(r'^Source: friend/(\w+) @ ([0-9a-f]{40})$', txt, re.M):
                recorded.add(m.group(2))
missing=[m for m in msgs if m[0] not in recorded]
print('S07 total',len(msgs),'missing',len(missing))
for m in sorted(missing,key=lambda x:x[1]):
    print(m[0],m[1],m[2],m[3])
